1	package com.loja.checkout.calculator;
2	
3	import com.loja.checkout.dto.ItemRequest;
4	import com.loja.checkout.enums.Cupom;
5	import com.loja.checkout.util.Arredondamento;
6	
7	import java.math.BigDecimal;
8	import java.util.List;
9	
10	public class CupomCalculator {
11	
12	    public static class Resultado {
13	        public BigDecimal desconto;
14	        public BigDecimal freteAjustado;
15	
16	        public Resultado(BigDecimal desconto, BigDecimal freteAjustado) {
17	            this.desconto = desconto;
18	            this.freteAjustado = freteAjustado;
19	        }
20	    }
21	
22	    public Resultado calcular(Cupom cupom, BigDecimal subtotal, List<ItemRequest> itens, BigDecimal frete) {
23	        if (cupom == null) {
24	            return new Resultado(BigDecimal.ZERO, frete);
25	        }
26	
27	        return switch (cupom) {
28	            case BEMVINDO10 -> desconto10Porcento(subtotal);
29	            case MENOS50 -> descontoMenos50(subtotal);
30	            case FRETEGRATIS -> descontoFrteGratis(frete);
31	            case LEVE3PAGUE2 -> descontoLeve3Pague2(itens);
32	        };
33	    }
34	
35	    private Resultado desconto10Porcento(BigDecimal subtotal) {
36	        BigDecimal desconto = subtotal.multiply(new BigDecimal("0.10"));
37	        return new Resultado(Arredondamento.paraCentavos(desconto), BigDecimal.ZERO);
38	    }
39	
40	    private Resultado descontoMenos50(BigDecimal subtotal) {
41	        return new Resultado(new BigDecimal("50.00"), BigDecimal.ZERO);
42	    }
43	
44	    private Resultado descontoFrteGratis(BigDecimal frete) {
45	        return new Resultado(frete, BigDecimal.ZERO);
46	    }
47	
48	    private Resultado descontoLeve3Pague2(List<ItemRequest> itens) {
49	        BigDecimal desconto = BigDecimal.ZERO;
50	
51	        for (ItemRequest item : itens) {
52	            if (item.quantidade() >= 3) {
53	                int quantidadeGratis = item.quantidade() / 3;
54	                BigDecimal descontoItem = item.precoUnitario().multiply(new BigDecimal(quantidadeGratis));
55	                desconto = desconto.add(descontoItem);
56	            }
57	        }
